    f=np.zeros(6);s.mj.mj_contactForce(m,d,i,f);N=c.frame[:3].copy();print(part,'pos_local',np.round(Ro.T@(c.pos-Po),3),'norm_world',np.round(N,3),'norm_obj',np.round(Ro.T@N,3),'force',np.round(f[:3],2))
